diff --git a/src/contract.ts b/src/contract.ts
index eaea291..0c5d4f4 100644
--- a/src/contract.ts
+++ b/src/contract.ts
@@ -1,14 +1,79 @@
+function asRecord(value: unknown): Record<string, unknown> | null {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    return null;
+  }
+  return value as Record<string, unknown>;
+}
+
+const OPERATOR_BUNDLE_ID = /^[a-z0-9-]{3,48}$/;
+const SYNTHETIC_ID = /^[a-z][a-z0-9-]{2,47}$/;
+
 export function fixtureFamilyId(root: unknown): string | null {
-  void root;
-  throw new Error("not implemented");
+  const rec = asRecord(root);
+  if (rec === null) {
+    return null;
+  }
+  if (rec.kind === "issue") {
+    const number = rec.number;
+    if (typeof number === "number" && Number.isInteger(number) && number >= 1) {
+      return "fam-" + String(number);
+    }
+    return null;
+  }
+  if (rec.kind === "operator_bundle") {
+    return typeof rec.id === "string" && OPERATOR_BUNDLE_ID.test(rec.id)
+      ? "fam-op-" + rec.id
+      : null;
+  }
+  if (rec.kind === "synthetic") {
+    return typeof rec.id === "string" && SYNTHETIC_ID.test(rec.id) ? "fam-syn-" + rec.id : null;
+  }
+  return null;
 }

 export function syntheticRootId(root: unknown): string | null {
-  void root;
-  throw new Error("not implemented");
+  const rec = asRecord(root);
+  if (rec === null || rec.kind !== "synthetic") {
+    return null;
+  }
+  return typeof rec.id === "string" && SYNTHETIC_ID.test(rec.id) ? rec.id : null;
 }

 export function checkFixtureContract(input: unknown): { ok: boolean; problems: string[] } {
-  void input;
-  throw new Error("not implemented");
+  const rec = asRecord(input);
+  if (rec === null) {
+    return { ok: false, problems: ["fixture_not_object"] };
+  }
+  const problems: string[] = [];
+  const familyId = fixtureFamilyId(rec.root);
+  if (familyId === null) {
+    problems.push("root_invalid");
+  } else if (rec.family_id !== familyId) {
+    problems.push("family_id_mismatch");
+  }
+  const rootRec = asRecord(rec.root);
+  const kind = rootRec === null ? null : rootRec.kind;
+  if (typeof rec.synthetic !== "boolean") {
+    problems.push("synthetic_not_boolean");
+  } else if (rec.synthetic !== (kind === "synthetic")) {
+    problems.push("synthetic_flag_mismatch");
+  }
+  const reconstructs = rec.reconstructs;
+  if (reconstructs !== null && reconstructs !== undefined) {
+    const reconRec = asRecord(reconstructs);
+    if (reconRec === null) {
+      problems.push("reconstructs_invalid");
+    } else {
+      if (rec.synthetic !== true) {
+        problems.push("reconstructs_requires_synthetic");
+      }
+      if (reconRec.kind === "synthetic") {
+        problems.push("reconstructs_synthetic_root");
+      }
+    }
+  }
+  if (rec.failure_type === null && rec.synthetic !== true) {
+    problems.push("failure_type_requires_synthetic");
+  }
+  return { ok: problems.length === 0, problems };
 }

